import{_ as a,a as r,c as t,ac as i}from"./chunks/framework.BSuaGltH.js";const d=JSON.parse('{"title":"告警：基础对象与机制","description":"按 告警责任、Pending/Firing、空数据、分组与通知路由 的实际关系组织。","frontmatter":{"title":"告警：基础对象与机制","description":"按 告警责任、Pending/Firing、空数据、分组与通知路由 的实际关系组织。","showdocs":{"topics":[{"id":"alerting","title":"告警与问题定位","link":"/topics/alerting/"}],"kind":"知识专题","scope":"general","audience":"general","group":"容器与运维","seriesTitle":"告警与问题定位机制与任务课程","summary":"按 告警责任、Pending/Firing、空数据、分组与通知路由 的实际关系组织。","status":"active","related":[{"title":"告警与问题定位：配置规则、分组与通知路由","link":"/systems/logging-monitoring/alerting/plus/practice/application","kind":"开发与配置实践","scope":"general","audience":"general"},{"title":"告警：发布、排障与恢复练习","link":"/systems/logging-monitoring/alerting/operations","kind":"知识专题","scope":"general","audience":"general"}],"prev":false,"next":{"text":"告警与问题定位：配置规则、分组与通知路由","link":"/systems/logging-monitoring/alerting/plus/practice/application"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"告警与问题定位：配置规则、分组与通知路由","link":"/systems/logging-monitoring/alerting/plus/practice/application"}},"headers":[],"relativePath":"systems/logging-monitoring/alerting/alert-lifecycle.md","filePath":"systems/logging-monitoring/alerting/alert-lifecycle.md"}'),n={name:"systems/logging-monitoring/alerting/alert-lifecycle.md"};function o(l,e,s,p,g,c){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="告警-基础对象与机制" tabindex="-1">告警：基础对象与机制 <a class="header-anchor" href="#告警-基础对象与机制" aria-label="Permalink to &quot;告警：基础对象与机制&quot;">​</a></h1><h2 id="part-1" tabindex="-1">告警条件、责任人与响应入口 <a class="header-anchor" href="#part-1" aria-label="Permalink to &quot;告警条件、责任人与响应入口 {#part-1}&quot;">​</a></h2><p>告警的目标是让负责人采取行动。先定义业务影响、阈值和处理入口，再区分规则计算、告警状态与通知投递；只有面板变红而没有明确责任人和恢复证据，响应链路仍不完整。</p><h3 id="part-1-ownership" tabindex="-1">告警责任与行动 <a class="header-anchor" href="#part-1-ownership" aria-label="Permalink to &quot;告警责任与行动 {#part-1-ownership}&quot;">​</a></h3><p>告警责任设计先定义用户影响、值班人和可执行处置，再写阈值。CPU高不必然影响用户，ERROR日志也不自动等于事故；优先让告警回答哪个服务出现什么影响、从哪里开始排查。规则引擎判断条件，Alertmanager聚合通知，接收端负责投递及升级，这三层健康需要分别观察。没有负责人和runbook的通知通常只增加噪声。</p><h3 id="part-1-commands" tabindex="-1">规则检查与管理入口 <a class="header-anchor" href="#part-1-commands" aria-label="Permalink to &quot;规则检查与管理入口 {#part-1-commands}&quot;">​</a></h3><p>告警管理入口中promtool test rules读取规则测试，amtool用于Alertmanager查询和管理；它们是产品CLI。规则检查只能证明某类语法或预期输入，不证明通知通道能送达。读者以后须在隔离环境核对版本、配置路径和目标地址，避免amtool对生产silence作写入；silence管理是一种状态变更，不能当只读命令复制。</p><h3 id="part-1-inputs" tabindex="-1">输入数据与安全边界 <a class="header-anchor" href="#part-1-inputs" aria-label="Permalink to &quot;输入数据与安全边界 {#part-1-inputs}&quot;">​</a></h3><p>告警输入数据应有稳定service和severity标签，任意用户输入不得直接进入标签或通知模板。模板可能包含内网路径、实例名与查询参数，通知到外部渠道前要裁剪敏感字段。规则表达式观察样本而非直接检查每个用户请求，采样缺失和评估失败必须有专门处理；本例没有账号、令牌或可用通知端点，不把保留域写成可部署配置。</p><h3 id="part-1-selfcheck" tabindex="-1">本篇练习与参考解答 <a class="header-anchor" href="#part-1-selfcheck" aria-label="Permalink to &quot;本篇练习与参考解答 {#part-1-selfcheck}&quot;">​</a></h3><p>练习：收到一条ERROR日志是否应该立即呼叫值班人？</p><details><summary>参考解答</summary><p>不必然。先确定用户影响、持续条件和可执行处置；日志事件、规则条件和通知投递是独立层。</p></details><h3 id="part-1-references" tabindex="-1">核对资料与相邻阅读 <a class="header-anchor" href="#part-1-references" aria-label="Permalink to &quot;核对资料与相邻阅读 {#part-1-references}&quot;">​</a></h3><ul><li><p><a href="https://prometheus.io/docs/prometheus/latest/configuration/alerting_rules/" target="_blank" rel="noopener noreferrer">Prometheus 3.x当前规则文档核对</a></p></li><li><p><a href="https://grafana.com/docs/grafana/latest/administration/provisioning/" target="_blank" rel="noopener noreferrer">Grafana provisioning核对</a></p></li><li><p><a href="https://prometheus.io/docs/prometheus/2.55/configuration/alerting_rules/" target="_blank" rel="noopener noreferrer">告警规则2.55</a></p></li><li><p><a href="https://prometheus.io/docs/alerting/0.28/configuration/" target="_blank" rel="noopener noreferrer">路由配置0.28</a></p></li><li><p><a href="https://prometheus.io/docs/alerting/latest/overview/" target="_blank" rel="noopener noreferrer">告警职责</a></p></li></ul><p>继续阅读<a href="#part-2-pending">机制</a>、<a href="/systems/logging-monitoring/alerting/plus/practice/application#files">完整实践</a>、<a href="/systems/logging-monitoring/alerting/operations#part-1-flap">运维</a>、<a href="/systems/logging-monitoring/alerting/operations#part-2-silent">诊断</a>与<a href="/systems/logging-monitoring/alerting/operations#part-3-exercise">复习</a>。</p><h2 id="part-2" tabindex="-1">状态机、持续时间与空数据 <a class="header-anchor" href="#part-2" aria-label="Permalink to &quot;状态机、持续时间与空数据 {#part-2}&quot;">​</a></h2><p>先明确规则标签、for、路由与接收端，再对照<a href="/systems/logging-monitoring/alerting/plus/practice/application#files">配套示例</a>理解pending/firing、静默/抑制与投递结果。</p><p>核对日期2026-10-17；适用范围：机制按核对时Prometheus 3.x官方文档的稳定共同子集说明；示例另固定Prometheus 2.55与Alertmanager 0.28教学配置族，归档族不是生产安装建议。新版新增或实验功能未默认启用，实际升级仍需独立兼容与安全评估。示例未执行；真实环境仍需验证产品配置、权限、连通与恢复结果。先读<a href="#part-1-ownership">起点</a>理解前置，再按章节完成推演。</p><h3 id="part-2-pending" tabindex="-1">Pending与Firing <a class="header-anchor" href="#part-2-pending" aria-label="Permalink to &quot;Pending与Firing {#part-2-pending}&quot;">​</a></h3><p>告警pending状态表示表达式已产生某标签集合，但尚未连续满足for时长；持续达到for后才进入firing。在本例未设置keep_firing_for时，任意一次求值条件不再成立会打断持续期，标签变化也会创建新实例。Prometheus 3.x还提供keep_firing_for控制已firing条件消失后的保持期，属于另一项恢复策略，本例未启用。for不是通知延迟总量，通知还受评估间隔、网络与group_wait影响。例子up=0持续2分钟触发，up恢复1即解除该规则，不把Alertmanager resolve_timeout误当Prometheus恢复等待。</p><h3 id="part-2-nodata" tabindex="-1">空数据与采集失败 <a class="header-anchor" href="#part-2-nodata" aria-label="Permalink to &quot;空数据与采集失败 {#part-2-nodata}&quot;">​</a></h3><p>告警空数据必须与数值零区分：up=0表示已有目标抓取失败，目标从发现列表消失后up可能完全不存在，up==0就不再返回该目标。absent_over_time观察窗口内是否完全缺样本；它通常产生汇总缺失信号，不能自动知道每台原目标身份。业务延迟为空不代表延迟为0；缺失规则、抓取失败与业务阈值应分别设计，并监控规则引擎本身。</p><h3 id="part-2-routing" tabindex="-1">分组路由与抑制 <a class="header-anchor" href="#part-2-routing" aria-label="Permalink to &quot;分组路由与抑制 {#part-2-routing}&quot;">​</a></h3><p>告警路由按标签选择接收端，group_by决定哪些通知合并，group_wait等候新组，group_interval控制组变化通知，repeat_interval控制重复提醒。抑制在一个根因告警存在时暂停相关次要通知，silence是有时限的人为匹配静默；两者都不改变Prometheus的firing。equal中的service若双方缺失可能视为相等，必须固定关键标签，避免一个故障抑制无关系统。</p><h3 id="part-2-selfcheck" tabindex="-1">本篇练习与参考解答 <a class="header-anchor" href="#part-2-selfcheck" aria-label="Permalink to &quot;本篇练习与参考解答 {#part-2-selfcheck}&quot;">​</a></h3><p>练习：up从0变成没有序列，TargetDown不触发是否说明恢复？</p><details><summary>参考解答</summary><p>不是。目标可能从发现列表消失，应核对期望清单与缺失窗口，独立区分合法下线和盲区。</p></details><h3 id="part-2-references" tabindex="-1">核对资料与相邻阅读 <a class="header-anchor" href="#part-2-references" aria-label="Permalink to &quot;核对资料与相邻阅读 {#part-2-references}&quot;">​</a></h3><p>本节沿用<a href="#part-1-references">本页资料与示例入口</a>。</p>',29)])])}const u=a(n,[["render",o]]);export{d as __pageData,u as default};
